import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const failingProvider = (reason: unknown): AIProvider =>
  ({
    sendMessage: () => ({[Symbol.asyncIterator]: () => ({next: () => Promise.reject(reason)})}),
  }) as unknown as AIProvider;

const seenByOnError = async (reason: unknown) => {
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(
    failingProvider(reason),
    new PromptBuilder({identity: 'You are a test assistant.'}),
    undefined,
    {
      hooks: {
        onError: async (_session, error) => {
          seen.push(error);
        },
      },
    }
  );
  const session = {
    sessionId: 'cause-session',
    userId: 'user-1',
    entries: [{role: 'user' as const, content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const thrown = await orchestrator.processMessage(session).then(
    () => 'resolved' as unknown,
    (e: unknown) => e
  );
  return {count: seen.length, cause: seen[0]?.cause, first: seen[0], thrown};
};

describe('onError receives the original rejection as cause', () => {
  it('wraps a string once, keeps it as cause, and rethrows it unchanged', async () => {
    const {count, cause, thrown} = await seenByOnError('string boom');

    expect({count, cause, thrown}).toEqual({count: 1, cause: 'string boom', thrown: 'string boom'});
  });

  it('wraps a plain object once, keeps it as cause, and rethrows it unchanged', async () => {
    const reason = {code: 503};

    const {count, cause, thrown} = await seenByOnError(reason);

    expect({count, cause, thrown}).toEqual({count: 1, cause: reason, thrown: reason});
  });

  it('wraps undefined once, keeps it as cause, and rethrows it unchanged', async () => {
    const {count, cause, thrown} = await seenByOnError(undefined);

    expect({count, cause, thrown}).toEqual({count: 1, cause: undefined, thrown: undefined});
  });

  it('passes an Error through as the same instance', async () => {
    const reason = new Error('boom');

    const {first} = await seenByOnError(reason);

    expect(first).toBe(reason);
  });
});
EOF
